11	// Renamed from csrc/kernels/cuda/_cutlass_gemm.cuh.
12	//
13	// Used by Muon (Newton-Schulz GEMMs) and SuperGrok v2 (dt_proj fused
14	// softplus). Gated behind -DWITH_CUTLASS. Without the flag, Muon falls
15	// back to cuBLAS (torch::mm) and SG2 uses cuBLAS + a separate softplus
