832	// Softplus+bias post-pass (used by SG2 dt_proj fused path).
833	static __global__ void softplus_bias_kernel(
834	    float* __restrict__ C, const float* __restrict__ bias,
835	    int M, int N)
836	{
837	    // 64-bit linear index: M*N (rows * d_inner for the SG2 dt_proj fused path)
838	    // can exceed INT_MAX for large parameter tensors. col stays in int (col<N).
839	    int64_t idx = static_cast<int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
840	    if (idx < static_cast<int64_t>(M) * N) {
841	        int col = static_cast<int>(idx % N);
842	        float val = C[idx] + bias[col];
843	        C[idx] = (val > 20.0f) ? val : logf(1.0f + expf(val));
844	    }
845	}
846	
847	inline void launch_softplus_bias(
848	    float* C, const float* bias, int M, int N,
849	    cudaStream_t stream)
850	{
851	    if (!bias) return;
852	    int64_t total = static_cast<int64_t>(M) * N;
853	    int block = 256;
854	    int grid = static_cast<int>((total + block - 1) / block);
855	    softplus_bias_kernel<<<grid, block, 0, stream>>>(C, bias, M, N);
856	}
