862	    const float* bias, float* C,
863	    cudaStream_t stream)
864	{
865	    cudaError_t err = gemm_fp16(M, N, K, A, B, C, stream);
866	    if (err != cudaSuccess) return err;
867	    launch_softplus_bias(C, bias, M, N, stream);
868	    return cudaSuccess;
