153	// Launch the unpipelined single-tile / K-loop GEMM for a compile-time N.
154	template <int N>
155	static torch::Tensor run_single_tile(torch::Tensor A, torch::Tensor B, int k_steps) {
156	    TORCH_CHECK(A.scalar_type() == torch::kBFloat16, "A must be bf16");
157	    TORCH_CHECK(B.scalar_type() == torch::kBFloat16, "B must be bf16");
158	    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "inputs must be CUDA");
159	    TORCH_CHECK(A.is_contiguous() && B.is_contiguous(), "inputs must be contiguous");
160	    TORCH_CHECK(A.numel() == (int64_t)k_steps * 64 * 16, "A numel mismatch");
161	    TORCH_CHECK(B.numel() == (int64_t)k_steps * N * 16,  "B numel mismatch");
162	
163	    auto D = torch::empty({64, N},
164	                          torch::dtype(torch::kFloat32).device(A.device()));
165	    size_t smem = single_tile_smem_bytes(N, k_steps);
166	    auto stream = at::cuda::getCurrentCUDAStream();
167	
168	    // Allow > 48 KB dynamic smem (opt-in attribute) for larger k_steps.
169	    cudaFuncSetAttribute(gemm_single_tile_kernel<N>,
170	                         cudaFuncAttributeMaxDynamicSharedMemorySize,
171	                         (int)smem);
172	    gemm_single_tile_kernel<N><<<1, 128, smem, stream>>>(
173	        reinterpret_cast<const __nv_bfloat16*>(A.data_ptr()),
174	        reinterpret_cast<const __nv_bfloat16*>(B.data_ptr()),
175	        D.data_ptr<float>(), k_steps);
176	    C10_CUDA_CHECK(cudaGetLastError());
177	    return D;
178	}
