182	static torch::Tensor run_pipelined(torch::Tensor A, torch::Tensor B, int k_steps) {
183	    TORCH_CHECK(A.scalar_type() == torch::kBFloat16 && B.scalar_type() == torch::kBFloat16);
184	    TORCH_CHECK(A.is_cuda() && B.is_cuda() && A.is_contiguous() && B.is_contiguous());
185	    auto D = torch::empty({64, N},
186	                          torch::dtype(torch::kFloat32).device(A.device()));
