189	    size_t ring = (size_t)PipeDepth * (64 * 16 + N * 16) * sizeof(__nv_bfloat16);
190	    size_t bars = (size_t)PipeDepth * 2 * sizeof(unsigned long long); // full+empty
191	    size_t smem = ring + bars + 256;  // slack for alignment
192	    auto stream = at::cuda::getCurrentCUDAStream();
193	    cudaFuncSetAttribute(gemm_pipelined_kernel<N, PipeDepth>,
194	                         cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
195	    gemm_pipelined_kernel<N, PipeDepth><<<1, 256, smem, stream>>>(
196	        reinterpret_cast<const __nv_bfloat16*>(A.data_ptr()),
197	        reinterpret_cast<const __nv_bfloat16*>(B.data_ptr()),
198	        D.data_ptr<float>(), k_steps);
199	    C10_CUDA_CHECK(cudaGetLastError());
200	    return D;
201	}
